## 3. 구현 상세 설계

### 3.1 공유 메모리 맵 (200줄)

```rust
// shared_memory.rs
use std::sync::{Arc, RwLock};
use std::collections::HashMap;
use std::fs::File;
use std::io::Read;

pub type FileId = u64;
pub type ModuleId = u64;

#[derive(Clone, Debug)]
pub struct SourceText {
    content: Arc<String>,
    file_id: FileId,
    hash: String,
}

#[derive(Clone, Debug)]
pub struct ASTMetadata {
    file_id: FileId,
    node_count: usize,
    depth: usize,
    dependencies: Vec<FileId>,
    last_modified: u64,
}

#[derive(Clone, Debug)]
pub struct IntermediateRepresentation {
    module_id: ModuleId,
    instructions: Vec<IRInstruction>,
    symbol_table: HashMap<String, Symbol>,
}

#[derive(Clone, Debug)]
pub enum IRInstruction {
    Load(String),
    Store(String),
    Call(String, Vec<String>),
    Return(String),
    // ... 추가 명령어
}

pub struct SharedMemoryPool {
    text_cache: Arc<RwLock<HashMap<FileId, Arc<SourceText>>>>,
    ast_index: Arc<RwLock<HashMap<FileId, ASTMetadata>>>,
    ir_cache: Arc<RwLock<HashMap<ModuleId, Arc<IntermediateRepresentation>>>>,
    file_hashes: Arc<RwLock<HashMap<String, FileId>>>,
    stats: Arc<CompilationStats>,
}

impl SharedMemoryPool {
    pub fn new() -> Self {
        Self {
            text_cache: Arc::new(RwLock::new(HashMap::new())),
            ast_index: Arc::new(RwLock::new(HashMap::new())),
            ir_cache: Arc::new(RwLock::new(HashMap::new())),
            file_hashes: Arc::new(RwLock::new(HashMap::new())),
            stats: Arc::new(CompilationStats::new()),
        }
    }

    pub fn load_text(&self, file_id: FileId, path: &str) -> Result<Arc<SourceText>> {
        let mut cache = self.text_cache.write().unwrap();

        if let Some(text) = cache.get(&file_id) {
            self.stats.cache_hits.fetch_add(1, Ordering::SeqCst);
            return Ok(text.clone());
        }

        let mut file = File::open(path)?;
        let mut content = String::new();
        file.read_to_string(&mut content)?;

        let hash = Self::compute_hash(&content);
        let text = Arc::new(SourceText {
            content: Arc::new(content),
            file_id,
            hash: hash.clone(),
        });

        cache.insert(file_id, text.clone());

        let mut hashes = self.file_hashes.write().unwrap();
        hashes.insert(hash, file_id);

        self.stats.cache_misses.fetch_add(1, Ordering::SeqCst);
        Ok(text)
    }

    pub fn cache_ast(&self, file_id: FileId, metadata: ASTMetadata) {
        let mut index = self.ast_index.write().unwrap();
        index.insert(file_id, metadata);
    }

    pub fn get_ast_metadata(&self, file_id: FileId) -> Option<ASTMetadata> {
        let index = self.ast_index.read().unwrap();
        index.get(&file_id).cloned()
    }

    pub fn cache_ir(&self, module_id: ModuleId, ir: IntermediateRepresentation) {
        let mut cache = self.ir_cache.write().unwrap();
        cache.insert(module_id, Arc::new(ir));
    }

    pub fn get_ir(&self, module_id: ModuleId) -> Option<Arc<IntermediateRepresentation>> {
        let cache = self.ir_cache.read().unwrap();
        cache.get(&module_id).cloned()
    }

    pub fn lookup_identical_files(&self, hash: &str) -> Vec<FileId> {
        let hashes = self.file_hashes.read().unwrap();
        if let Some(&file_id) = hashes.get(hash) {
            vec![file_id]
        } else {
            vec![]
        }
    }

    fn compute_hash(content: &str) -> String {
        use std::collections::hash_map::DefaultHasher;
        use std::hash::{Hash, Hasher};

        let mut hasher = DefaultHasher::new();
        content.hash(&mut hasher);
        format!("{:x}", hasher.finish())
    }

    pub fn stats(&self) -> Arc<CompilationStats> {
        self.stats.clone()
    }

    pub fn memory_usage(&self) -> usize {
        let text_size: usize = self.text_cache
            .read()
            .unwrap()
            .values()
            .map(|t| t.content.len())
            .sum();

        let ast_size = self.ast_index.read().unwrap().len() * 256; // 추정
        let ir_size: usize = self.ir_cache
            .read()
            .unwrap()
            .values()
            .map(|ir| ir.instructions.len() * 16)
            .sum();

        text_size + ast_size + ir_size
    }
}

pub struct CompilationStats {
    total_files: AtomicUsize,
    compiled_files: AtomicUsize,
    total_time_ms: AtomicU64,
    memory_used_bytes: AtomicUsize,
    cache_hits: AtomicUsize,
    cache_misses: AtomicUsize,
}

impl CompilationStats {
    pub fn new() -> Self {
        Self {
            total_files: AtomicUsize::new(0),
            compiled_files: AtomicUsize::new(0),
            total_time_ms: AtomicU64::new(0),
            memory_used_bytes: AtomicUsize::new(0),
            cache_hits: AtomicUsize::new(0),
            cache_misses: AtomicUsize::new(0),
        }
    }

    pub fn throughput_files_per_sec(&self) -> f64 {
        let time_s = self.total_time_ms.load(Ordering::SeqCst) as f64 / 1000.0;
        let files = self.compiled_files.load(Ordering::SeqCst) as f64;
        if time_s > 0.0 { files / time_s } else { 0.0 }
    }

    pub fn cache_hit_ratio(&self) -> f64 {
        let hits = self.cache_hits.load(Ordering::SeqCst) as f64;
        let misses = self.cache_misses.load(Ordering::SeqCst) as f64;
        let total = hits + misses;
        if total > 0.0 { hits / total } else { 0.0 }
    }
}
```

### 3.2 병렬 컴파일 엔진 (150줄)

```rust
// parallel_compiler.rs
use rayon::ThreadPool;
use std::sync::{Arc, Mutex};
use std::collections::{HashMap, VecDeque};

pub struct DependencyGraph {
    edges: HashMap<FileId, Vec<FileId>>, // file_id -> dependencies
}

impl DependencyGraph {
    pub fn new() -> Self {
        Self { edges: HashMap::new() }
    }

    pub fn add_dependency(&mut self, file_id: FileId, depends_on: FileId) {
        self.edges.entry(file_id)
            .or_insert_with(Vec::new)
            .push(depends_on);
    }

    pub fn topological_sort(&self) -> Vec<Vec<FileId>> {
        // 의존성 없는 파일들을 그룹화
        let mut groups: Vec<Vec<FileId>> = vec![];
        let mut visited = std::collections::HashSet::new();
        let mut in_degree: HashMap<FileId, usize> = HashMap::new();

        // in-degree 계산
        for (_, deps) in &self.edges {
            for &dep in deps {
                *in_degree.entry(dep).or_insert(0) += 1;
            }
        }

        // BFS를 통한 레벨별 그룹화
        let mut queue: VecDeque<FileId> = VecDeque::new();

        for file_id in self.edges.keys() {
            if in_degree.get(file_id).copied().unwrap_or(0) == 0 {
                queue.push_back(*file_id);
            }
        }

        while !queue.is_empty() {
            let level_size = queue.len();
            let mut level: Vec<FileId> = vec![];

            for _ in 0..level_size {
                if let Some(file_id) = queue.pop_front() {
                    level.push(file_id);

                    for (dependent, deps) in &self.edges {
                        if deps.contains(&file_id) {
                            let current_degree = in_degree.get(dependent).copied().unwrap_or(0);
                            if current_degree > 1 {
                                in_degree.insert(*dependent, current_degree - 1);
                            } else {
                                queue.push_back(*dependent);
                            }
                        }
                    }
                }
            }

            if !level.is_empty() {
                groups.push(level);
            }
        }

        groups
    }
}

pub struct CompileTask {
    pub file_id: FileId,
    pub path: String,
    pub module_id: ModuleId,
}

pub type TaskHandle = u64;

pub struct ParallelCompiler {
    pool: Arc<SharedMemoryPool>,
    thread_pool: ThreadPool,
    dependency_graph: Mutex<DependencyGraph>,
    next_task_id: AtomicU64,
}

impl ParallelCompiler {
    pub fn new(pool: Arc<SharedMemoryPool>, num_threads: usize) -> Self {
        Self {
            pool,
            thread_pool: rayon::ThreadPoolBuilder::new()
                .num_threads(num_threads)
                .build()
                .unwrap(),
            dependency_graph: Mutex::new(DependencyGraph::new()),
            next_task_id: AtomicU64::new(0),
        }
    }

    pub fn add_dependency(&self, file_id: FileId, depends_on: FileId) {
        let mut graph = self.dependency_graph.lock().unwrap();
        graph.add_dependency(file_id, depends_on);
    }

    pub fn compile_parallel(&self, files: Vec<(FileId, String, ModuleId)>)
        -> Result<Vec<CompiledModule>>
    {
        let graph = self.dependency_graph.lock().unwrap();
        let groups = graph.topological_sort();

        let mut results = Vec::new();

        for group in groups {
            let pool = self.pool.clone();
            let compiled_group = self.thread_pool.install(|| {
                group.into_iter().map(|file_id| {
                    self.compile_single(file_id, &pool)
                }).collect::<Result<Vec<_>>>()
            })?;

            results.extend(compiled_group);
        }

        Ok(results)
    }

    fn compile_single(&self, file_id: FileId, pool: &Arc<SharedMemoryPool>)
        -> Result<CompiledModule>
    {
        let start = std::time::Instant::now();

        // 1. 텍스트 로드 (공유 메모리에서)
        let text = pool.load_text(file_id, "dummy_path")?;

        // 2. AST 생성 또는 캐시에서 로드
        let ast_meta = if let Some(meta) = pool.get_ast_metadata(file_id) {
            meta
        } else {
            // 간단한 AST 생성 시뮬레이션
            ASTMetadata {
                file_id,
                node_count: text.content.len() / 50, // 추정치
                depth: 10,
                dependencies: vec![],
                last_modified: 0,
            }
        };

        // 3. IR 생성 또는 캐시에서 로드
        let module_id = file_id as ModuleId;
        let ir = if let Some(cached_ir) = pool.get_ir(module_id) {
            cached_ir.as_ref().clone()
        } else {
            let ir = IntermediateRepresentation {
                module_id,
                instructions: vec![],
                symbol_table: HashMap::new(),
            };
            pool.cache_ir(module_id, ir.clone());
            ir
        };

        let elapsed = start.elapsed();

        Ok(CompiledModule {
            file_id,
            module_id,
            ir,
            compile_time_ms: elapsed.as_millis() as u64,
        })
    }

    pub fn schedule_task(&self, task: CompileTask) -> TaskHandle {
        let task_id = self.next_task_id.fetch_add(1, Ordering::SeqCst);
        // 실제 구현에서는 task queue에 추가
        task_id
    }
}

pub struct CompiledModule {
    pub file_id: FileId,
    pub module_id: ModuleId,
    pub ir: IntermediateRepresentation,
    pub compile_time_ms: u64,
}

pub struct Symbol {
    pub name: String,
    pub type_: String,
    pub scope: String,
}
